// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }

    function testFuzz_property(address newOwner) public {
        // The test contract (deployer) is c's current owner. Restrict the domain:
        // newOwner must differ from the caller so the mutation is observable.
        vm.assume(newOwner != address(this));

        // Owner (the test contract) calls setOwner directly.
        bool ok;
        try c.setOwner(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        // Rule: a successful owner call transfers ownership to exactly newOwner.
        assertTrue(ok && c.owner() == newOwner);
    }
}
